package com.checa.crm.mapper;

import com.checa.crm.pojo.entity.ProductEntities;
import org.apache.ibatis.annotations.*;
import java.util.List;

@Mapper
public interface ProductMapper {
 // ---------------- 产品分类 ----------------
 @Select({"<script>","select c.category_id categoryId,c.department_id departmentId,c.parent_id parentId,c.category_name categoryName,pc.category_name parentName,c.sort_num sortNum,c.path,c.description,c.status,(select count(*) from crm_sku s join crm_product p on p.product_id=s.product_id and p.deleted=0 where p.category_id=c.category_id and s.deleted=0) productCount,c.create_time createdTime from crm_category c left join crm_category pc on pc.category_id=c.parent_id and pc.deleted=0 where c.deleted=0","<if test='keyword!=null and keyword!=&quot;&quot;'> and c.category_name like concat('%',#{keyword},'%')</if>","<if test='status!=null and status!=&quot;&quot;'> and c.status=#{status}</if>","<if test='categoryIds!=null'> and c.category_id in <foreach collection='categoryIds' item='d' open='(' separator=',' close=')'>#{d}</foreach></if>","order by c.sort_num,c.category_id","</script>"}) List<ProductEntities.Category> categories(@Param("keyword")String keyword,@Param("status")String status,@Param("categoryIds")List<String> categoryIds);
 @Select("select c.category_id categoryId,c.department_id departmentId,c.parent_id parentId,c.category_name categoryName,pc.category_name parentName,c.sort_num sortNum,c.path,c.description,c.status,(select count(*) from crm_sku s join crm_product p on p.product_id=s.product_id and p.deleted=0 where p.category_id=c.category_id and s.deleted=0) productCount,c.create_time createdTime from crm_category c left join crm_category pc on pc.category_id=c.parent_id and pc.deleted=0 where c.category_id=#{id} and c.deleted=0") ProductEntities.Category category(@Param("id")String id);
 @Select("select category_id from crm_category where category_name=#{name} and deleted=0 order by sort_num limit 1") String categoryIdByName(@Param("name")String name);
 @Select("select count(*) from crm_category where parent_id=#{parent} and category_name=#{name} and category_id<>#{id} and deleted=0") int sameCategory(@Param("parent")String parent,@Param("name")String name,@Param("id")String id);
 @Select("select count(*) from crm_category where parent_id=#{id} and deleted=0") int childCategories(@Param("id")String id);
 @Select("with recursive cte as (select category_id from crm_category where category_id=#{id} and deleted=0 union all select c.category_id from crm_category c join cte on c.parent_id=cte.category_id and c.deleted=0) select category_id from cte") List<String> categorySubtree(@Param("id")String id);
 @Select("with recursive cte as (select category_id,parent_id from crm_category where category_id=#{id} and deleted=0 union all select c.category_id,c.parent_id from crm_category c join cte on c.category_id=cte.parent_id and c.deleted=0) select category_id from cte") List<String> categoryAncestors(@Param("id")String id);
 @Select("with recursive cte as (select category_id from crm_category where parent_id=#{id} and deleted=0 union all select c.category_id from crm_category c join cte on c.parent_id=cte.category_id and c.deleted=0) select count(*) from cte where category_id=#{parent}") int descendantCount(@Param("id")String id,@Param("parent")String parent);
 @Insert("insert into crm_category(category_id,department_id,parent_id,category_name,sort_num,path,description,status,deleted) values(#{id},#{dept},#{parent},#{name},#{sort},#{path},#{description},#{status},0)") int addCategory(@Param("id")String id,@Param("dept")String dept,@Param("parent")String parent,@Param("name")String name,@Param("sort")Integer sort,@Param("path")String path,@Param("description")String description,@Param("status")String status);
 @Update("update crm_category set parent_id=#{parent},category_name=#{name},sort_num=#{sort},path=#{path},description=#{description},status=#{status} where category_id=#{id} and deleted=0") int updateCategory(@Param("id")String id,@Param("parent")String parent,@Param("name")String name,@Param("sort")Integer sort,@Param("path")String path,@Param("description")String description,@Param("status")String status);
 @Update("update crm_category set status=#{status} where category_id=#{id} and deleted=0") int updateCategoryStatus(@Param("id")String id,@Param("status")String status);
 @Update("update crm_category set deleted=1 where category_id=#{id}") int deleteCategory(@Param("id")String id);

 // ---------------- 产品档案（SPU） ----------------
 @Select("select product_id productId,department_id departmentId,category_id categoryId,product_name productName,brand,applicable_scenes applicableScenes,image_url imageUrl,sales_tags salesTags,usage_note usageNote,related_products relatedProducts,substitute_products substituteProducts,status,description,(select count(*) from crm_sku s where s.product_id=crm_product.product_id and s.deleted=0) skuCount from crm_product where product_id=#{id} and deleted=0") ProductEntities.Product productById(@Param("id")String id);
 @Insert("insert into crm_product(product_id,department_id,category_id,product_name,brand,applicable_scenes,image_url,sales_tags,usage_note,related_products,substitute_products,status,description,deleted) values(#{id},#{dept},#{category},#{name},#{brand},#{scenes},#{image},#{tags},#{usage},#{related},#{substitute},#{status},#{description},0)") int addProduct(@Param("id")String id,@Param("dept")String dept,@Param("category")String category,@Param("name")String name,@Param("brand")String brand,@Param("scenes")String scenes,@Param("image")String image,@Param("tags")String tags,@Param("usage")String usage,@Param("related")String related,@Param("substitute")String substitute,@Param("status")String status,@Param("description")String description);
 @Update("update crm_product set product_name=#{name},brand=#{brand},applicable_scenes=#{scenes},image_url=#{image},sales_tags=#{tags},usage_note=#{usage},related_products=#{related},substitute_products=#{substitute},description=#{description} where product_id=#{id} and deleted=0") int updateProduct(@Param("id")String id,@Param("name")String name,@Param("brand")String brand,@Param("scenes")String scenes,@Param("image")String image,@Param("tags")String tags,@Param("usage")String usage,@Param("related")String related,@Param("substitute")String substitute,@Param("description")String description);
 @Update("update crm_product set category_id=#{category} where product_id=#{id} and deleted=0") int updateProductCategory(@Param("id")String id,@Param("category")String category);
 @Update("update crm_product set status=#{status} where product_id=#{id} and deleted=0") int updateProductStatus(@Param("id")String id,@Param("status")String status);
 @Update("update crm_product set deleted=1 where product_id=#{id}") int deleteProduct(@Param("id")String id);

 // ---------------- SKU ----------------
 @Select("select sku_id skuId,product_id productId,sku_code skuCode,spec,packaging,conversion,unit,repurchase_cycle repurchaseCycle,standard_price standardPrice,stock,status from crm_sku where sku_id=#{id} and deleted=0") ProductEntities.Sku sku(@Param("id")String id);
 @Select("select product_id from crm_product where product_name=#{name} and category_id=#{category} and deleted=0 order by create_time limit 1") String productIdByNameAndCategory(@Param("name")String name,@Param("category")String category);
 @Select("select count(*) from crm_sku where product_id=#{id} and deleted=0") int countSkusOfProduct(@Param("id")String id);
 @Select("select count(*) from crm_sku where product_id=#{id} and deleted=0 and status=#{status}") int countSkusOfProductByStatus(@Param("id")String id,@Param("status")String status);
 @Select("select count(*) from crm_sku where sku_code=#{code} and sku_id<>#{id}") int skuCount(@Param("code")String code,@Param("id")String id);
 @Insert("insert into crm_sku(sku_id,product_id,sku_code,spec,packaging,conversion,unit,repurchase_cycle,standard_price,stock,status,deleted) values(#{id},#{productId},#{code},#{spec},#{packaging},#{conversion},#{unit},#{cycle},#{price},#{stock},#{status},0)") int addSku(@Param("id")String id,@Param("productId")String productId,@Param("code")String code,@Param("spec")String spec,@Param("packaging")String packaging,@Param("conversion")String conversion,@Param("unit")String unit,@Param("cycle")String cycle,@Param("price")Object price,@Param("stock")Object stock,@Param("status")String status);
 @Update("update crm_sku set sku_code=#{code},spec=#{spec},packaging=#{packaging},conversion=#{conversion},unit=#{unit},repurchase_cycle=#{cycle},standard_price=#{price},stock=#{stock},status=#{status} where sku_id=#{id} and deleted=0") int updateSku(@Param("id")String id,@Param("code")String code,@Param("spec")String spec,@Param("packaging")String packaging,@Param("conversion")String conversion,@Param("unit")String unit,@Param("cycle")String cycle,@Param("price")Object price,@Param("stock")Object stock,@Param("status")String status);
 @Update("update crm_sku set status=#{status} where sku_id=#{id} and deleted=0") int updateSkuStatus(@Param("id")String id,@Param("status")String status);
 @Update("update crm_sku set deleted=1 where sku_id=#{id}") int deleteSku(@Param("id")String id);

 // ---------------- 产品 + SKU 平铺视图 ----------------
 String SKU_ROW_COLUMNS = "select s.sku_id skuId,s.product_id productId,p.department_id departmentId,p.category_id categoryId,c.category_name categoryName,p.product_name productName,p.brand,p.applicable_scenes applicableScenes,p.image_url imageUrl,p.sales_tags salesTags,p.usage_note usageNote,p.related_products relatedProducts,p.substitute_products substituteProducts,p.status productStatus,p.description,s.sku_code skuCode,s.spec,s.packaging,s.conversion,s.unit,s.repurchase_cycle repurchaseCycle,s.standard_price standardPrice,s.stock,s.status skuStatus,(select count(*) from crm_sku s2 where s2.product_id=p.product_id and s2.deleted=0) skuCount,s.create_time createdTime from crm_sku s join crm_product p on p.product_id=s.product_id and p.deleted=0 join crm_category c on c.category_id=p.category_id and c.deleted=0 where s.deleted=0 ";
 @Select({"<script>",SKU_ROW_COLUMNS,"<if test='keyword!=null and keyword!=&quot;&quot;'> and (p.product_name like concat('%',#{keyword},'%') or s.sku_code like concat('%',#{keyword},'%'))</if>","<if test='status!=null and status!=&quot;&quot;'> and s.status=#{status}</if>","<if test='category!=null and category!=&quot;&quot;'> and c.category_name=#{category}</if>","<if test='categoryIds!=null'> and p.category_id in <foreach collection='categoryIds' item='d' open='(' separator=',' close=')'>#{d}</foreach></if>","<if test='productId!=null and productId!=&quot;&quot;'> and p.product_id=#{productId}</if>","<if test='deptId!=null and deptId!=&quot;&quot;'> and p.department_id=#{deptId}</if>","order by p.create_time desc,s.create_time,s.sku_id","</script>"}) List<ProductEntities.ProductSku> productSkus(@Param("keyword")String keyword,@Param("status")String status,@Param("category")String category,@Param("categoryIds")List<String> categoryIds,@Param("productId")String productId,@Param("deptId")String deptId);
 @Select(SKU_ROW_COLUMNS+" and s.sku_id=#{id}") ProductEntities.ProductSku productSku(@Param("id")String id);
 @Select(SKU_ROW_COLUMNS+" and p.product_id=#{id} order by s.create_time,s.sku_id limit 1") ProductEntities.ProductSku firstSkuOfProduct(@Param("id")String id);
 @Select(SKU_ROW_COLUMNS+" and p.product_id=#{id} order by s.create_time,s.sku_id") List<ProductEntities.ProductSku> skusOfProduct(@Param("id")String id);
 @Select(SKU_ROW_COLUMNS+" and s.sku_code=#{code} limit 1") ProductEntities.ProductSku productSkuByCode(@Param("code")String code);
 @Select(SKU_ROW_COLUMNS+" and p.product_name=#{name} order by s.create_time,s.sku_id limit 1") ProductEntities.ProductSku productSkuByName(@Param("name")String name);
 @Select("select count(*) from crm_customer_price where sku_id=#{id} and deleted=0") int priceCountBySku(@Param("id")String id);
 @Select("select count(*) from crm_customer_price where product_id=#{id} and deleted=0") int priceCountByProduct(@Param("id")String id);

 // ---------------- 客户价格 ----------------
 @Select({"<script>","select x.price_id priceId,x.department_id departmentId,x.customer_id customerId,c.customer_name customerName,x.product_id productId,p.product_name productName,x.sku_id skuId,s.sku_code sku,x.customer_level customerLevel,x.price_type priceType,x.min_quantity minQuantity,x.max_quantity maxQuantity,x.price,x.minimum_price minimumPrice,x.start_date startDate,x.end_date endDate,x.priority,x.status,x.note,x.create_time createdTime from crm_customer_price x join crm_customer c on c.customer_id=x.customer_id and c.deleted=0 join crm_sku s on s.sku_id=x.sku_id and s.deleted=0 join crm_product p on p.product_id=s.product_id and p.deleted=0 where x.deleted=0","<if test='keyword!=null and keyword!=&quot;&quot;'> and (c.customer_name like concat('%',#{keyword},'%') or p.product_name like concat('%',#{keyword},'%') or s.sku_code like concat('%',#{keyword},'%'))</if>","<if test='status!=null and status!=&quot;&quot;'> and x.status=#{status}</if>","<if test='customer!=null and customer!=&quot;&quot;'> and c.customer_name=#{customer}</if>","<if test='deptIds!=null'> and x.department_id in <foreach collection='deptIds' item='d' open='(' separator=',' close=')'>#{d}</foreach></if>","<if test='categoryIds!=null'> and p.category_id in <foreach collection='categoryIds' item='d' open='(' separator=',' close=')'>#{d}</foreach></if>","order by x.priority desc,x.create_time desc","</script>"}) List<ProductEntities.Price> prices(@Param("keyword")String keyword,@Param("status")String status,@Param("customer")String customer,@Param("deptIds")List<String> deptIds,@Param("categoryIds")List<String> categoryIds);
 @Select("select x.price_id priceId,x.department_id departmentId,x.customer_id customerId,c.customer_name customerName,x.product_id productId,p.product_name productName,x.sku_id skuId,s.sku_code sku,x.customer_level customerLevel,x.price_type priceType,x.min_quantity minQuantity,x.max_quantity maxQuantity,x.price,x.minimum_price minimumPrice,x.start_date startDate,x.end_date endDate,x.priority,x.status,x.note,x.create_time createdTime from crm_customer_price x join crm_customer c on c.customer_id=x.customer_id and c.deleted=0 join crm_sku s on s.sku_id=x.sku_id and s.deleted=0 join crm_product p on p.product_id=s.product_id and p.deleted=0 where x.price_id=#{id} and x.deleted=0") ProductEntities.Price price(@Param("id")String id);
 @Select("select customer_id from crm_customer where customer_name=#{name} and deleted=0 order by (department_id=#{dept}) desc,customer_id limit 1") String customerId(@Param("name")String name,@Param("dept")String dept);
 @Select("select department_id from crm_customer where customer_id=#{id} and deleted=0") String customerDepartment(@Param("id")String id);
 @Select({"<script>","select customer_id customerId,department_id departmentId,customer_name customerName,customer_level customerLevel,status from crm_customer where deleted=0","<if test='keyword!=null and keyword!=&quot;&quot;'> and customer_name like concat('%',#{keyword},'%')</if>","<if test='deptIds!=null'> and department_id in <foreach collection='deptIds' item='d' open='(' separator=',' close=')'>#{d}</foreach></if>","order by customer_name","</script>"}) List<ProductEntities.Customer> customers(@Param("keyword")String keyword,@Param("deptIds")List<String> deptIds);
 @Insert("insert into crm_customer_price(price_id,department_id,customer_id,product_id,sku_id,customer_level,price_type,min_quantity,max_quantity,price,minimum_price,start_date,end_date,priority,status,note,deleted) values(#{id},#{dept},#{customer},#{product},#{sku},#{level},#{type},#{min},#{max},#{price},#{minimum},str_to_date(#{start},'%Y-%m-%d'),str_to_date(nullif(#{end},''),'%Y-%m-%d'),#{priority},#{status},#{note},0)") int addPrice(@Param("id")String id,@Param("dept")String dept,@Param("customer")String customer,@Param("product")String product,@Param("sku")String sku,@Param("level")String level,@Param("type")String type,@Param("min")Object min,@Param("max")Object max,@Param("price")Object price,@Param("minimum")Object minimum,@Param("start")String start,@Param("end")String end,@Param("priority")Integer priority,@Param("status")String status,@Param("note")String note);
 @Update("update crm_customer_price set customer_id=#{customer},product_id=#{product},sku_id=#{sku},customer_level=#{level},price_type=#{type},min_quantity=#{min},max_quantity=#{max},price=#{price},minimum_price=#{minimum},start_date=str_to_date(#{start},'%Y-%m-%d'),end_date=str_to_date(nullif(#{end},''),'%Y-%m-%d'),priority=#{priority},status=#{status},note=#{note} where price_id=#{id} and deleted=0") int updatePrice(@Param("id")String id,@Param("customer")String customer,@Param("product")String product,@Param("sku")String sku,@Param("level")String level,@Param("type")String type,@Param("min")Object min,@Param("max")Object max,@Param("price")Object price,@Param("minimum")Object minimum,@Param("start")String start,@Param("end")String end,@Param("priority")Integer priority,@Param("status")String status,@Param("note")String note);
 @Update("update crm_customer_price set deleted=1 where price_id=#{id}") int deletePrice(@Param("id")String id);
 @Update("update crm_customer_price set status=#{status} where price_id=#{id} and deleted=0") int updatePriceStatus(@Param("id")String id,@Param("status")String status);
}
